// go: sdk 1.25.5 regexp/syntax/perl_groups.go:26-33 perlGroup
/// Go: `var perlGroup = map[string]charGroup{…}`.
///
/// goish looks these up with a linear scan rather than a map: six
/// entries keyed on two-byte strings, and the parser reaches it once
/// per `\d` in a pattern. Go uses a map because Go has map literals;
/// the lookup is not where either spends its time.
pub(crate) fn perlGroup(name: &string) -> Option<charGroup> {
    let n = name.as_bytes();
    if n.len() != 2 || n[0] != b'\\' {
        return None;
    }
    return match n[1] {
        b'd' => Some(charGroup { sign: 1, class: &code1 }),
        b'D' => Some(charGroup { sign: -1, class: &code1 }),
        b's' => Some(charGroup { sign: 1, class: &code2 }),
        b'S' => Some(charGroup { sign: -1, class: &code2 }),
        b'w' => Some(charGroup { sign: 1, class: &code3 }),
        b'W' => Some(charGroup { sign: -1, class: &code3 }),
        _ => None,
    };
}

// go: sdk 1.25.5 regexp/syntax/perl_groups.go:104-133 posixGroup
/// Go: `var posixGroup = map[string]charGroup{…}` — the fourteen POSIX
/// names, each in a positive and a `[:^name:]` negated form.
///
/// Same scan-not-map note as [`perlGroup`].
pub(crate) fn posixGroup(name: &string) -> Option<charGroup> {
    let table: [(&str, &[rune]); 14] = [
        ("alnum", &code4),
        ("alpha", &code5),
        ("ascii", &code6),
        ("blank", &code7),
        ("cntrl", &code8),
        ("digit", &code9),
        ("graph", &code10),
        ("lower", &code11),
        ("print", &code12),
        ("punct", &code13),
        ("space", &code14),
        ("upper", &code15),
        ("word", &code16),
        ("xdigit", &code17),
    ];
    let n = name.as_bytes();
    // Every key is `[:name:]` or `[:^name:]`.
    if n.len() < 5 || n[0] != b'[' || n[1] != b':' || n[n.len() - 2] != b':' || n[n.len() - 1] != b']'
    {
        return None;
    }
    let (sign, body) = if n[2] == b'^' {
        (-1, &n[3..n.len() - 2])
    } else {
        (1, &n[2..n.len() - 2])
    };
    for (nm, class) in table.iter() {
        if body == nm.as_bytes() {
            return Some(charGroup {
                sign,
                class,
            });
        }
    }
    return None;
}
